// Obtenemos el texto de salida del AI Agent
const texto = $input.first().json.output;

// Expresión regular para detectar AMBOS formatos de URLs de Google Drive:
// Formato 1: https://drive.google.com/uc?id=...
// Formato 2: https://drive.google.com/file/d/.../view...
const urlMatches = texto.match(/https:\/\/drive\.google\.com\/(uc\?id=|file\/d\/)[^\s)]+/g);

// Extraemos todas las URLs si existen (como array)
const imageUrls = urlMatches ? urlMatches : [];

// Removemos el formato Markdown de imagen y TODAS las URLs del texto
const textoLimpio = texto
  .replace(/!\[.*?\]\(https:\/\/drive\.google\.com\/(uc\?id=|file\/d\/)[^\s)]+\)/g, '')
  .replace(/https:\/\/drive\.google\.com\/(uc\?id=|file\/d\/)[^\s)]+/g, '')
  .trim();

// Construimos el payload para el mensaje de texto
const payload = {
  content: textoLimpio,
  private: false,
  message_type: "outgoing",
  sender: { type: "bot" }
};

// Convertimos a JSON
const cuerpoJSON = JSON.stringify(payload);

// Retornamos el mensaje y TODAS las URLs extraídas
return {
  json: {
    cuerpoJSON: cuerpoJSON,
    imageUrls: imageUrls,  // Array con todas las URLs
    imageCount: imageUrls.length,  // Cantidad de imágenes encontradas
    textoLimpio: textoLimpio
  }
};

const text = $input.first().json.content;
